def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _legacy_mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    from collections import defaultdict

    graph = defaultdict(list)
    for ordering in orderings:
        for i in range(len(ordering) - 1):
            u, v = ordering[i], ordering[i + 1]
            graph[u].append(v)

    in_degree = {node: 0 for node in set(edge for edges in graph.values() for edge in edges) | set(graph.keys())}
    for u in graph:
        for v in graph[u]:
            in_degree[v] += 1

    zero_in_degree = [node for node in in_degree if in_degree[node] == 0]
    merged_ordering = []

    while zero_in_degree:
        if len(zero_in_degree) > 1:
            # If there's more than one node with zero in-degree, we need to ensure
            # that the orderings are preserved based on the first appearance.
            # Here, we arbitrarily choose the first one in the list for simplicity.
            # In practice, additional logic may be needed to resolve this.
