    """Return a pretty formatted representation of self."""
    indent_str = '  ' * indent
    pretty_str = f"{indent_str}{self.__class__.__name__}:"
    if debug:
        pretty_str += f" id={getattr(self, 'id', None)}"
    pretty_str += '\n'
    for attr, value in self.__dict__.items():
        if attr[0] != '_':
            if isinstance(value, list):
                pretty_str += f"{indent_str}  {attr}:\n"
                for item in value:
                    if hasattr(item, 'pretty'):
                        pretty_str += item.pretty(indent + 2, debug)
                    else:
                        pretty_str += f"{indent_str}    {item}\n"
            elif hasattr(value, 'pretty'):
                pretty_str += f"{indent_str}  {attr}:\n" + value.pretty(indent + 2, debug)
            else:
                pretty_str += f"{indent_str}  {attr}: {value}\n"
    return pretty_str

