def normalized(self):
    """
    Return a version of this object represented entirely using integer
    values for the relative attributes.

    >>> relativedelta(days=1.5, hours=2).normalized()
    relativedelta(days=+1, hours=+14)

    :return:
        Returns a :class:`dateutil.relativedelta.relativedelta` object.
    """
    normalized = relativedelta()
    for attr in self._fields:
        value = getattr(self, attr)
        if value is not None:
            if attr in ['years', 'months', 'weeks', 'days']:
                # Convert non-integer days to a combination of days and hours
                if attr == 'days' and not isinstance(value, int):
                    days, remainder_hours = divmod(value, 1)
                    normalized.days += int(days)
                    normalized.hours += int(remainder_hours * 24)
                else:
                    normalized.__setattr__(attr, int(value))
            elif attr in ['hours', 'minutes', 'seconds', 'microseconds']:
                normalized.__setattr__(attr, int(value))
            else:
                normalized.__setattr__(attr, value)
    return normalized

