def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_arguments = {}
    remaining_arguments = unparsed_arguments.copy()

    for name, parser in subparsers.items():
        parsed, remaining = parser.parse_known_args(unparsed_arguments)
        parsed_arguments[name] = parsed
        remaining_arguments = [arg for arg in remaining_arguments if arg in remaining]

    return parsed_arguments, remaining_arguments

