def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    import re
    tags = set()
    code_block = False
    in_tag = False
    tag_word = []
    result = []

    def is_code_block_fence(line):
        return line.strip().startswith('```')

    lines = text.split('\n')
    for line in lines:
        if is_code_block_fence(line):
            code_block = not code_block
        if not code_block:
            i = 0
            while i < len(line):
                char = line[i]
                if char == '#':
                    in_tag = True
                    tag_word = ['#']
                elif in_tag and char.isalnum() or char in ('_', '-'):
                    tag_word.append(char)
                else:
                    if in_tag and len(tag_word) > 1:
                        tag = ''.join(tag_word)
                        tags.add(tag)
                        if replacer:
                            replaced = replacer(tag)
                            result.append(replaced)
                        else:
                            result.append(tag)
                    else:
                        result.append(''.join(tag_word))
                    tag_word = []
                    in_tag = False
                    result.append(char)
                i += 1
            if in_tag and len(tag_word) > 1:
                tag = ''.join(tag_word)
                tags.add(tag)
                if replacer:
                    replaced = replacer(tag)
                    result.append(replaced)
                else:
                    result.append(tag)
            result.append('\n')
        else:
            result.append(line)
            result.append('\n')

    return tags, ''.join(result).rstrip('\n')

